(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.02-t*0.22)*16 + Math.sin(x*0.016+t*0.3)*11;
  const w2x = Math.sin((x+w1x)*0.012+t*0.15)*10 + Math.cos((y+w1y)*0.01-t*0.12)*8;
  const w2y = Math.cos((y+w1y)*0.014-t*0.17)*9 + Math.sin((x+w1x)*0.011+t*0.2)*7;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [240+Math.sin(t*0.4)*120+Math.cos(t*0.7)*40, 120+Math.cos(t*0.35)*80+Math.sin(t*0.6)*30, 0.07, 2.2],
    [240+Math.cos(t*0.5)*100+Math.sin(t*0.8)*50, 120+Math.sin(t*0.55)*90+Math.cos(t*0.45)*35, 0.09, 1.8],
    [240+Math.sin(t*0.3+2)*130, 120+Math.cos(t*0.45+1)*100, 0.055, 2.5],
    [120+Math.cos(t*0.65+1)*90+Math.sin(t*0.9)*30, 180+Math.sin(t*0.5+3)*70, 0.11, 1.6],
    [360+Math.sin(t*0.38+4)*100, 60+Math.cos(t*0.75+2)*80, 0.065, 2.8],
    [240+Math.cos(t*0.32+5)*110, 200+Math.sin(t*0.48)*70, 0.085, 2.0],
    [160+Math.sin(t*0.55+1.5)*60, 50+Math.cos(t*0.4+2.5)*40, 0.12, 1.4],
    [320+Math.cos(t*0.6+3)*70, 190+Math.sin(t*0.5+1)*50, 0.1, 1.7]
  ];
  let aS = 0, iS = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp);
    iS += Math.sin(d*f*0.7+t*sp*0.5+1.5)+Math.sin(d*f*1.3-t*sp*0.8+0.7);
  }
  const act = aS/8, inh = iS/16;
  const bg1 = (Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.038+t))/2;
  const bg2 = Math.sin((sx+sy)*0.1+t*2.2)*0.2+Math.sin((sx-sy)*0.085-t*1.8)*0.2;
  const bg3 = Math.sin(sx*0.08+t*0.5)*Math.sin(sy*0.065-t*0.4)*0.3;
  const bg = bg1+bg2+bg3;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.045-ang*3-t*1.3)+Math.sin(dist*0.035+ang*4-t)+Math.sin(dist*0.06-ang*2+t*0.8)*0.5)/2.5;
  const cX = sx*0.08, cY = sy*0.08;
  const ciX = Math.round(cX), ciY = Math.round(cY);
  let minD = 99;
  for (let dx = -1; dx <= 1; dx++) for (let dy = -1; dy <= 1; dy++) {
    const ncx = ciX+dx+Math.sin((ciX+dx)*1.7+t*0.3)*0.4;
    const ncy = ciY+dy+Math.cos((ciY+dy)*2.1+t*0.25)*0.4;
    const cd = Math.sqrt((cX-ncx)**2+(cY-ncy)**2);
    if (cd < minD) minD = cd;
  }
  const sm = (v,e0,e1) => Math.max(0,Math.min(1,(v-e0)/(e1-e0)));
  const cellEdge = 1-sm(minD, 0.05, 0.15);
  const rd = Math.tanh((act-inh*0.65+bg*0.25+spiral*0.35-cellEdge*0.4)*2);
  const ripple = Math.sin(sx*0.2+sy*0.15+t*3)*Math.sin(sx*0.12-sy*0.18-t*2.5)*0.15;
  const blend = rd*0.7+cellEdge*0.15+ripple*0.15;
  const v = blend*0.5+0.5;
  const pal = [[5,12,52],[10,45,95],[15,85,120],[20,140,135],[80,180,140],[180,200,100],[230,180,80],[220,130,70],[180,75,75],[120,40,70],[60,20,55],[5,12,52]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.85+Math.sin(rd*Math.PI)*0.15;
  const edge = Math.abs(rd)>0.75?1.12:1.0;
  const glow = Math.max(0, rd*0.8)*0.15;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*60)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*40)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*20)|0)
  ];
}
